extractions.extraction_text:
1 En los edificios de uso Residencial Vivienda con altura de evacuación superior a 28 m, de uso Residencial Público , Administrativo o Docente con altura de evacuación superior a 14 m, de uso Comercial o Pública concurrencia con altura de evacuación superior a 10 m o en plantas de uso Aparcamiento cuya superficie exceda de 1.500 m 2 , toda planta que no sea zona de ocupación nula y que no disponga de alguna salida del edificio accesible dispondrá de posibilidad de paso a un sector de incendio alternativo mediante una salida de planta accesible o bien de una zona de refugio apta para el número de plazas que se indica a continuación:
-una para usuario de silla de ruedas por cada 100 ocupantes o fracción, conforme a SI3-2;
-excepto en uso Residencial Vivienda , una para persona con otro tipo de movilidad reducida por cada 33 ocupantes o fracción, conforme a SI3-2 .

attributes.satisfied_if:
HAS(FLOOR.EXIT.ACCESSIBLE.ALTERNATIVE_FIRE_SECTOR) == TRUE OR (
            HAS(FLOOR.REFUGE_AREA) == TRUE AND (
                REFUGE_AREA.CAPACITY.WHEELCHAIR_USERS >= (FLOOR.OCCUPANTS / 100) OR REFUGE_AREA.CAPACITY.WHEELCHAIR_USERS >= 1
            ) AND (
                BUILDING.USAGE != 'RESIDENTIAL.HOUSING' AND (REFUGE_AREA.CAPACITY.REDUCED_MOBILITY_OTHER >= (FLOOR.OCCUPANTS / 33) OR REFUGE_AREA.CAPACITY.REDUCED_MOBILITY_OTHER >= 1)
            )
        )
